typedef float rational_t;
typedef float vm_num_t;

class stringx
{
public:
  stringx();
  stringx(const stringx&);
  ~stringx();
};

stringx operator+(const stringx&, const char*);
stringx operator+(const stringx&, const stringx&);
void error(const stringx&);

class script_object
{
public:
  class instance
  {
    int unused;
    stringx name;
  public:
    const stringx& get_name() const { return name; }
  };

private:
  int unused[3];
  stringx fullname;
public:
  const stringx& get_fullname() const { return fullname; }
};

class vm_thread
{
  script_object::instance* instance_ptr;
  script_object* executable;
public:
  script_object::instance* get_instance() const { return instance_ptr; }
  script_object* get_executable() const { return executable; }
};

class vm_stack
{
public:
  int salloc;
  char* buffer;
  char* SP;
private:
  vm_thread* my_thread;
public:
  char* get_SP() const { return SP; }
  vm_thread* get_thread() const { return my_thread; }
  void pop(int n) { SP -= n; }
  bool push(const char* src, int n);
};

class vector3d
{
public:
  rational_t x;
  rational_t y;
  rational_t z;
};

inline bool operator==(const vector3d& a, const vector3d& b)
{
  return (a.x == b.x) && (a.y == b.y) && (a.z == b.z);
}

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };

    virtual bool operator()(vm_stack& stack, entry_t entry) { return true; }
  };
};

#define SLF_PARMS \
  stack.pop(sizeof(parms_t)); \
  parms_t* parms = (parms_t*)stack.get_SP()

#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result)) ) \
    error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() )

#define SLF_DONE \
  return true

class slf_vector3d_equal_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vector3d me;
    vector3d b;
  };

  virtual bool operator()(vm_stack& stack,entry_t entry);
};

bool slf_vector3d_equal_t::operator()(vm_stack& stack,entry_t entry)
{
  SLF_PARMS;
  vm_num_t result = (parms->me == parms->b);
  SLF_RETURN;
  SLF_DONE;
}
